namespace OpenTPW;

/// <summary>
/// The kart and water track slice's approximation register (docs/TRACKS.md). Each entry is tagged <c>[APPROX:TRACK-NNN]</c> at its code site (a retired one leaves its BIN labels, a reclassified one an <c>[EXT:name]</c> decision, docs/TRACKS.md); the
/// words before the colon name the topic. Everything else of the slice is traced from the Mac and Windows binaries (BIN labels at the code sites).
/// </summary>
public static class TrackApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("TRACK-010", "TRACK-BRIDGE (narrowed in round 11): the tile ops are tp.exe's, run in the x86 oracle on 700 random layouts (TrackBridges): a path or queue stays under a tile (the type op never writes the cell's type, 0x538FC0; only a line's last tile removes the paths under it, 0x5390C0), the base op 0x538A92 and the path tool's 0x534115 give the whole flag word 1, the op 0x86 walks 0x52C6F0 and 0x52CCB0 round the ride give 2, 8 and 4, a path taken off a tile runs no op (0x5367A0). Residual: a walk that runs past the structure array (a track end with an arm into empty ground reads on until the 16-bit id wraps) ends false where the executable reads other game memory, and the type-25 rule (map types 2, 7 and 30 under a hoarding) has no case since OpenTPW writes no type 25"),
				("TRACK-032", "SAVED-RIDE TRACK: an original save's kart or water track is imported from the structure layer's track cells (the 31-byte cells, loader 0x4D0B30 and 0x50C200: the type 11 and 13 kart and 16 and 18 water tiles and their type-12 extensions with their connection mask, flow link, flags, origin, chosen piece, overlap, alternate mask and segment; the ride of a tile is the one whose station reaches it through the masks) and each ride's circuit is walked from them, compared with chunk 4's section list and given chunk 3's words (the laps, the performance, the model words +0x14 and +0x18 the loader stores raw, and the phase; Level.ImportOriginalTracks; loader 0x543560: the ride chunk 0x543638, the section chunk 0x543FF4 through the section builder 0x54B2F0); once the guest import has made the riders, the vehicles (chunk 5: the 43 words of the 0xAC-byte record, the collision object found from the vehicle's place or the fallback place of the chunk, the aimed waypoint found from its key), their riders (chunk 9, with their seat numbers) and the joining and leaving lists (chunks 8 and 7, the join refused for a ride in phase 0, one peep list of 1024 nodes for every ride) are put on the controller as the loader leaves them, every list reversed because the loader pushes each node on the head again, the phase raw (a racing or over kart or water ride keeps it), the chunk-6 reference waypoint the walk's own (the open routine 0x544840 picks the same one) and nothing drawn from the world generator, as the loader neither launches a vehicle (0x54A040) nor hangs a head (0x44B410) (Level.ImportOriginalTrackRiders, BumpController.ImportOriginalVehicles, tp.exe 0x543B3C..0x543F24); a ride whose chunks do not read like the saver's, whose vehicle stands in no collision object (the module tick 0x546C80 reads the object unchecked) or aims at a waypoint of another ride, or that names a guest who is not a rider of it, is refused with its reason and keeps no vehicle (a kart or water ride saved racing or over then waits in loading); a bumper ride's chunks (ride words, phase, vehicles, riders and lists, which the loader 0x543560 reads as for a kart ride) are not imported, and the guests who rode a ride whose vehicles were not imported are put off the ride (SAVE-002); not imported: the flag bits of the track cells above 0x1F (the structure cell's mFlags is the layout the map cell shares, where tp.exe's cell code sets 0x20, 0x40 and 0x80 for other meanings, and its meaning on a track record is not read; OpenTPW's saves of before round 11 hold 0x20 as the bridge-over-path memory it no longer writes), the mesh-instance words of the cells and vehicles (+4 of a cell, +8 and +0xC of a vehicle: engine handles the loader binds again, 0x463AB0, which OpenTPW's renderers make anew) and the voice and emitter handles of a vehicle (+0x20, +0x2C: a boat's voice and a smoking car's emitter start again as after a park resume); a tile over a path or queue cell keeps that cell's type and lies beneath it (0x538FC0, TRACK-010); no save of the corpus or Easymode holds a kart, water or bumper ride (their TrackRides block is the 44-byte build-stamp chunk), so the import is checked against the saver's shapes and OpenTPW's own tracks only"),
	};
}
